{	return (Ch >= '0') && (Ch <= '9');}//----------------------------------------------------------------------------------------// SetEditCommandName: Sets the Edit menu command name to the custom name, e.g. 'Copy// Cells'.//----------------------------------------------------------------------------------------void SetEditCommandName(CommandNumber theCommand, 						CommandNumber customCommand){	SetCommandName(theCommand, CommandToName(customCommand));}//----------------------------------------------------------------------------------------// SetTheFont: //----------------------------------------------------------------------------------------void SetTheFont(short fontNumber,				short fontSize,				Style fontStyle){	TextFont(fontNumber);	TextSize(fontSize);	TextFace(fontStyle);}//----------------------------------------------------------------------------------------// SmartDrawString: Draws the CPascalStr_AC at the [h,v] coordinate, taking into account the// width and justification.//----------------------------------------------------------------------------------------void SmartDrawString(CStr255_AC& theString,					 CRect_AC area,					 short justification){	FitString(theString, area.right - area.left);	MADrawString(theString, area, justification);}//----------------------------------------------------------------------------------------// ReadScrap: Utility for extracting data from the scrap, where scrapOffset indicates the// start of the data within the scrap handle, and dataLength is the length of the data to// be extracted. dataLength is added to scrapOffset.//----------------------------------------------------------------------------------------void ReadScrap(Handle theScrap,			   long& scrapOffset,			   void* theData,			   short dataLength){	BlockMove_AC(*theScrap + scrapOffset, theData, dataLength);	scrapOffset += dataLength;}//----------------------------------------------------------------------------------------// WriteScrap:  Utility for appending data to the end of the scrap handle //----------------------------------------------------------------------------------------void WriteScrap(Handle theScrap,				long& scrapOffset,				void* theData,				short dataLength){	SetHandleSize(theScrap, scrapOffset + dataLength);	::ThrowIfMemError_AC();	BlockMove_AC(theData, *theScrap + scrapOffset, dataLength);	scrapOffset += dataLength;}//----------------------------------------------------------------------------------------// End of CalcUtilities.cp/*	Historical Change Record:		----- R11 -----		06/26/96	Install release marker.  Scope many globals.  Change TRUE/FALSE/NULL.		04/26/96	Make and use an overload of CommandToName that returns a CStr255_AC function result.		----- R10 -----		----- 3.3b1 -----		  7/5/95	Cosmetic. 		 3/28/95	Eliminate unnecessary includes. 		02/22/95	1222850 MacApp should use BlockMove_AC and BlockMoveOverlap_AC everywhere*/